INSERT INTO products (category_id, name, slug, description, price, discount, stock, active, featured, main_image_url) VALUES
('c3333333-3333-3333-3333-333333333333', 'Acetato Fotocopiadora Laser x50 216 X 279', 'acetato-fotocopiadora-laser-x50-216-x-279-9500', 'Acetato Fotocopiadora Láser x50 Unidades 216x279 Calidad y Precisión para Tus Impresiones Profesionales El Acetato Fotocopiadora Láser x50 Unidades 216x279 es ideal para trabajos de impresión que requieren alta calidad y durabilidad. Con su tamaño estándar de 216x279 mm, este producto es perfecto para fotocopiadoras láser y ofrece un rendimiento óptimo para crear impresiones nítidas y claras. Perfecto para presentaciones, proyectos de oficina o cualquier necesidad profesional.', 15970.00, 20, 51, true, true, 'https://www.abastece.co/abastece/images/9500.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Adaptador Para Calculadora Casio Hr-100', 'adaptador-para-calculadora-casio-hr-100-3325', 'Adaptador para Calculadora Casio HR-100 x Unidad Alimentación estable que optimiza el funcionamiento continuo del equipo Adaptador de corriente para calculadora Casio HR-100, fabricado en material resistente de alta durabilidad, diseñado para suministrar energía eléctrica estable y segura al equipo, permitiendo su uso continuo en entornos de oficina, contabilidad o administrativos, su sistema de conexión es compatible con el modelo indicado garantizando un desempeño eficiente y reduciendo el uso de baterías, favoreciendo la estandarización en accesorios de alimentación y aportando a la continuidad operativa mediante un insumo estratégico que optimiza la productividad, la eficiencia energética y el funcionamiento ininterrumpido del dispositivo.', 23678.00, 20, 27, true, true, 'https://www.abastece.co/abastece/images/3325.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Aditivo Vybar 103 500gr', 'aditivo-vybar-103-500gr-72560', 'Aditivo Vybar 103 500 g Optimización de estructura y desempeño en formulaciones de cera para resultados consistentes Aditivo Vybar 103 en presentación de 500 g, utilizado en formulaciones de ceras y parafinas para mejorar la retención de fragancia, aumentar la viscosidad y estabilizar la estructura del producto final, garantizando una mejor integración de componentes; su incorporación permite mayor estabilidad del producto, mejor acabado superficial y optimización del rendimiento en procesos de fabricación, contribuyendo a la estandarización de lotes productivos y a la continuidad operativa en entornos de manufactura que requieren consistencia técnica y control de calidad.', 68719.00, 20, 35, true, false, 'https://www.abastece.co/abastece/images/72560.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Agenda Permanente Generica', 'agenda-permanente-generica-3191', 'Agenda Permanente Memorando Genérica Organización eficiente para tu día a día La Agenda Permanente Memorando Genérica es la herramienta perfecta para mantener tus tareas y recordatorios organizados. Con un diseño práctico y sencillo, esta agenda te permite llevar un seguimiento continuo de tus actividades sin necesidad de fechas preestablecidas, adaptándose a tu ritmo y necesidades. Ideal para oficinas, estudiantes o profesionales que buscan un control eficiente de sus responsabilidades diarias. Su formato compacto y hojas de alta calidad aseguran una experiencia de uso cómoda y duradera, mientras que su diseño atemporal hace que puedas utilizarla durante todo el año sin preocuparte por la fecha.', 10486.00, 20, 26, true, false, 'https://www.abastece.co/abastece/images/3191.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Alfiler Triton Galvanizados Caja 50g', 'alfiler-triton-galvanizados-caja-50g-74863', 'Caja de Alfiler Galvanizado Triton - 50g ¡Resistencia a la oxidación y punta de alta precisión para fijaciones impecables! La Caja de Alfiler Galvanizado Triton de 50g ofrece un insumo de alta calidad diseñado para tareas que requieren precisión y durabilidad. Gracias a su recubrimiento galvanizado, estos alfileres presentan una resistencia superior a la corrosión, evitando manchas de óxido en tejidos o documentos importantes. Su punta ultra afilada permite una perforación suave sin dañar las fibras de las telas ni romper el papel, garantizando una sujeción firme y segura. Es el insumo indispensable para la dotación de talleres de confección, estudios de diseño de modas, oficinas para la organización de carteleras y tableros de corcho, y centros de manualidades. Por su excelente relación costo-beneficio y el respaldo de la marca Triton, es un producto de alta rotación en papelería técnica, suministros de mercería y proveeduría para artes gráficas.', 1689.00, 20, 31, true, false, 'https://www.abastece.co/abastece/images/74863.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Almohadilla Dactilar Para 4000 Huellas 0E-560', 'almohadilla-dactilar-para-4000-huellas-0e-560-2336', 'Almohadilla Dactilar para 4000 Huellas 0E-560 Registro biométrico confiable con alta capacidad de uso continuo y precisión operativa Almohadilla dactilar modelo 0E-560 con capacidad aproximada para 4000 impresiones, diseñada para sistemas de registro manual de huellas en procesos de identificación, control de asistencia o validación documental, formulada con tinta de alta adherencia y secado controlado que garantiza nitidez en cada impresión; su desempeño permite registro biométrico legible, reducción de errores de marcación y mayor durabilidad de uso, contribuyendo a la estandarización de procesos de control y a la continuidad operativa en entornos administrativos y de gestión documental.', 1746.00, 20, 21, true, false, 'https://www.abastece.co/abastece/images/2336.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Almohadilla Dactilar Prevent Security X4000 Huellas', 'almohadilla-dactilar-prevent-security-x4000-huellas-3935', 'Almohadilla Dactilar Prevent Security x4000 Huellas Registro de huellas confiable para control eficiente de acceso y trazabilidad operativa Almohadilla dactilar marca Prevent Security con capacidad aproximada para 4000 impresiones, formulada con tinta de alta definición y secado controlado para garantizar registros claros y consistentes en sistemas manuales de identificación; su composición permite alta nitidez en la huella, reducción de fallas en el registro y uso prolongado en ciclos continuos, contribuyendo a la estandarización de procesos de control de ingreso y a la continuidad operativa en entornos donde la verificación de identidad y la trazabilidad documental son críticas.', 4552.00, 20, 38, true, false, 'https://www.abastece.co/abastece/images/3935.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Almohadilla Dactilar Rhezt x12.000 Huellas RHE-33', 'almohadilla-dactilar-rhezt-x12000-huellas-rhe-33-75165', 'Almohadilla Dactilar para 12.000 Huellas Rhezt Ref: RHE-33 Rendimiento prolongado para control eficiente de registro manual Almohadilla dactilar Rhezt referencia RHE-33 diseñada para soportar hasta 12.000 impresiones, con tinta de alta definición que garantiza huellas nítidas y uniformes en cada aplicación. Su superficie de entintado optimizada permite una transferencia consistente, reduciendo la necesidad de reposición frecuente y asegurando un desempeño estable en procesos de marcación y verificación manual.', 34222.00, 20, 22, true, false, 'https://www.abastece.co/abastece/images/75165.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Almohadilla Dactilar Rhezt x8000 Huellas RHE-34', 'almohadilla-dactilar-rhezt-x8000-huellas-rhe-34-1089', 'Almohadilla Dactilar para 8000 Huellas Rhezt Ref RHE-34 Precisión y Durabilidad en Cada Impresión Presentamos la almohadilla dactilar Rhezt Ref RHE-34, ideal para registrar hasta 8000 huellas con claridad y precisión. Su diseño ergonómico y su tinta de alta calidad aseguran que cada impresión sea nítida y duradera, perfecta para usos profesionales y de seguridad. Asegúrate de contar con un producto confiable para todas tus necesidades de toma de huellas.', 21298.00, 20, 41, true, false, 'https://www.abastece.co/abastece/images/1089.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Almohadilla Especial Rhezt Para Sello Grande RHE-249', 'almohadilla-especial-rhezt-para-sello-grande-rhe-249-76158', 'Almohadilla Especial Para Sello Grande Rhezt RHE-249 Impresión uniforme para sellos de alto formato y uso continuo Almohadilla especial Rhezt RHE-249 diseñada para sellos de gran tamaño, con superficie de entintado de alta cobertura que permite una transferencia homogénea de la tinta, asegurando impresiones claras y definidas en cada uso. Su composición optimiza la retención del color y mantiene un desempeño estable durante aplicaciones repetitivas, facilitando resultados consistentes en procesos de marcación de alto volumen.', 37854.00, 20, 19, true, false, 'https://www.abastece.co/abastece/images/76158.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Almohadilla Para Sellos', 'almohadilla-para-sellos-8552', 'Almohadilla para Sellos Impresión nítida y constante para control documental eficiente Almohadilla para sellos fabricada con base entintada de alta absorción, diseñada para garantizar transferencia uniforme de tinta en procesos de marcación manual, con compatibilidad para sellos de goma de uso administrativo; su formulación permite impresiones definidas, secado controlado y consistencia en la aplicación, contribuyendo a la estandarización del registro documental y a la continuidad operativa en flujos administrativos donde se requiere precisión, legibilidad y repetibilidad en la validación de información.', 2117.00, 20, 15, true, false, 'https://www.abastece.co/abastece/images/8552.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Anilladora Selecta Carta Para Anillo Plastico 8621', 'anilladora-selecta-carta-para-anillo-plastico-8621-71894', 'Anilladora Carta Selecta Para Anillo Plástico Ref: 8621 Encuadernación eficiente para documentos organizados y de fácil manejo Anilladora formato carta Selecta referencia 8621 diseñada para perforar y encuadernar documentos mediante anillos plásticos, permitiendo una sujeción firme y una manipulación sencilla de archivos. Su sistema de perforación controlada facilita el armado de presentaciones, manuales y reportes con acabado uniforme, optimizando el orden documental y asegurando una operación constante en entornos de trabajo administrativo.', 210504.00, 20, 42, true, false, 'https://www.abastece.co/abastece/images/71894.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Anillo Espiral Plastico 12mm x10 Tiras X 1m', 'anillo-espiral-plastico-12mm-x10-tiras-x-1m-73291', 'Anillo Espiral Plástico 12 mm Paq. x10 Tiras x 1 m c/u Encuadernación flexible y ordenada para gestión eficiente de documentos Anillos espirales plásticos de 12 mm en presentación de 10 tiras de 1 metro cada una, fabricados en material flexible de alta resistencia, diseñados para sistemas de encuadernación manual o automática que permiten el ensamble seguro de documentos; su estructura facilita apertura y cierre controlado, alineación uniforme de hojas y manipulación constante sin deformación, contribuyendo a la estandarización de procesos documentales y a la continuidad operativa en entornos administrativos, educativos y corporativos donde se requiere organización eficiente y presentación consistente de información.', 26287.00, 20, 15, true, false, 'https://www.abastece.co/abastece/images/73291.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Anillo Plastico De  42 Aros 8mm X 20u.', 'anillo-plastico-de-42-aros-8mm-x-20u-71435', 'Anillo Plástico de 42 Aros 8 mm x 20 u. Encuadernación precisa para organización documental continua y estandarizada Anillos plásticos de encuadernación con 42 aros y diámetro de 8 mm, presentación de 20 unidades, fabricados en material flexible de alta resistencia, diseñados para el ensamble y sujeción de documentos en sistemas de archivo manual; su estructura permite alineación uniforme de hojas, apertura controlada sin deformación y manipulación repetida sin pérdida de forma, contribuyendo a la estandarización del orden documental y a la continuidad operativa en procesos administrativos, educativos y corporativos donde se requiere eficiencia en la gestión de información.', 5520.00, 20, 42, true, false, 'https://www.abastece.co/abastece/images/71435.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Anillo Plastico De 42 Aros 14mm X 10', 'anillo-plastico-de-42-aros-14mm-x-10-70879', 'Anillo Plástico de 42 Aros 14mm x 10u Encuadernación práctica para organización documental eficiente Anillos plásticos de 42 aros con diámetro de 14 mm, presentados en paquete de 10 unidades, diseñados para sistemas de encuadernación que requieren sujeción firme y apertura flexible de documentos. Su estructura permite un giro uniforme de las páginas y una manipulación sencilla, garantizando un armado limpio y consistente en presentaciones, reportes y material administrativo, con desempeño estable en uso continuo.', 8473.00, 20, 18, true, false, 'https://www.abastece.co/abastece/images/70879.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Anillo Plastico De 42 Aros 9mm X 20', 'anillo-plastico-de-42-aros-9mm-x-20-71429', 'Anillo Plástico de 42 Aros 9mm x 20u Encudernación compacta para documentos livianos y bien organizados Anillos plásticos de 42 aros con diámetro de 9 mm, presentados en paquete de 20 unidades, diseñados para la encuadernación de documentos de bajo a medio volumen, garantizando sujeción firme y apertura flexible para una lectura continua. Su formato permite un giro uniforme de las hojas y un acabado ordenado, facilitando la organización de informes, apuntes y material administrativo con eficiencia operativa y uso constante.', 11105.00, 20, 33, true, false, 'https://www.abastece.co/abastece/images/71429.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Anillos Doble 00 Paso 3 : 1  14 Mm X 100 Unidades', 'anillos-doble-00-paso-3-1-14-mm-x-100-unidades-9495', 'Anillos Doble 00 Paso 3:1 14 mm x 100 Unidades Fijación robusta para encuadernación eficiente en volúmenes documentales exigentes Anillos metálicos doble 00 con paso 3:1 y diámetro de 14 mm, presentación de 100 unidades, diseñados para sistemas de encuadernación que requieren mayor capacidad de sujeción y resistencia estructural en documentos perforados, fabricados en material metálico de alta durabilidad para uso intensivo; su configuración permite cierre firme y estable, resistencia al uso continuo y alineación consistente de archivos, contribuyendo a la estandarización de procesos de archivo y a la continuidad operativa en entornos administrativos, técnicos y corporativos de alto volumen documental.', 63869.00, 20, 46, true, false, 'https://www.abastece.co/abastece/images/9495.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Anillos Doble 00 Paso 3 : 1  9 Mm X  100 Unidades', 'anillos-doble-00-paso-3-1-9-mm-x-100-unidades-9493', 'Anillos Doble 00 Paso 3:1 9 mm x 100 Unidades Encuadernación compacta y precisa para organización documental ligera y eficiente Anillos metálicos doble 00 con paso 3:1 y diámetro de 9 mm, presentación de 100 unidades, diseñados para sistemas de encuadernación de bajo volumen que requieren sujeción firme y alineación exacta de documentos perforados, fabricados en material metálico de alta resistencia para uso continuo; su estructura permite cierre seguro y uniforme, manipulación constante sin deformación y acabado limpio en archivos, contribuyendo a la estandarización de procesos documentales y a la continuidad operativa en entornos administrativos, educativos y corporativos donde se prioriza la organización eficiente de información.', 22982.00, 20, 41, true, false, 'https://www.abastece.co/abastece/images/9493.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Archivador  Fuelle 13 Bolsillos Carta Solido OE-450', 'archivador-fuelle-13-bolsillos-carta-solido-oe-450-75555', 'Archivador Fuelle 13 Bolsillos Carta Sólido OE-450 Organización documental segmentada para control eficiente de información en movimiento Archivador tipo fuelle modelo OE-450 con 13 bolsillos tamaño carta, fabricado en material plástico rígido de alta resistencia, diseñado para la clasificación y separación de documentos mediante expansión tipo acordeón que facilita el acceso rápido a la información; su estructura permite organización segmentada eficiente, protección del contenido documental y manejo ágil de archivos, contribuyendo a la estandarización del orden administrativo y a la continuidad operativa en entornos donde la gestión documental requiere movilidad, claridad y acceso inmediato a la información.', 11688.00, 20, 22, true, false, 'https://www.abastece.co/abastece/images/75555.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Archivador Fuelle 1/2 Carta  Plastico  13 Bolsillos', 'archivador-fuelle-12-carta-plastico-13-bolsillos-73990', 'Archivador Fuelle 1/2 Carta Plástico 13 Bolsillos: Organización y Practicidad para tu Oficina El archivador ideal para mantener tus documentos organizados y al alcance El Archivador Fuelle 1/2 Carta Plástico 13 Bolsillos es la solución perfecta para organizar tus documentos de manera eficiente y ordenada. Con capacidad para 13 bolsillos, este archivador te permite clasificar y guardar hojas de tamaño carta (1/2 carta) de forma segura. Su diseño compacto y flexible es ideal para oficinas, escuelas y uso doméstico, permitiéndote acceder fácilmente a tus archivos sin complicaciones. Fabricado en plástico resistente, este archivador asegura durabilidad y protección para tus documentos importantes, manteniéndolos organizados y en perfecto estado.', 5242.00, 20, 27, true, false, 'https://www.abastece.co/abastece/images/73990.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Archivador Fuelle Oficio', 'archivador-fuelle-oficio-0235', 'Archivador Fuelle Oficio: Organización Eficiente para tu Oficina Aumenta tu Productividad con este Archivador de Gran Capacidad El Archivador Fuelle Oficio es la solución perfecta para mantener tus documentos y papeles organizados de manera eficiente en tu oficina. Con su diseño de fuelle expandible y capacidad para documentos de tamaño oficio, podrás almacenar una gran cantidad de archivos sin sacrificar el orden. Mejora tu productividad y mantén tu espacio de trabajo ordenado con este archivador de alta calidad.', 14877.00, 20, 28, true, false, 'https://www.abastece.co/abastece/images/0235.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Archivador Manija Expandible 13 Bolsillos Oficio OE-455', 'archivador-manija-expandible-13-bolsillos-oficio-oe-455-71335', 'Archivador Manija Expandible 13 Bolsillos Oficio OE-455 Organiza tus documentos con facilidad y eficiencia El Archivador Manija Expandible 13 Bolsillos Oficio OE-455 es la solucion perfecta para mantener tus documentos organizados. Con 13 bolsillos expansibles, podras clasificar y almacenar tus papeles de manera ordenada y accesible. Su diseño robusto y manija para facil transporte lo convierte en el archivador ideal para oficina, escuela o uso personal. Organiza tu espacio de trabajo y manten todo bajo control con el Archivador Offi-Esco OE-455.', 12166.00, 20, 23, true, false, 'https://www.abastece.co/abastece/images/71335.jpg'),
('c3333333-3333-3333-3333-333333333333', 'AZ Carta Abastece Plastificado Azul', 'az-carta-abastece-plastificado-azul-9150', 'AZ Carta Azul Plastificado - Marca Abastece Calidad y Versatilidad para tus Documentos Conoce nuestra AZ carta azul plastificado de la marca Abastece, perfecta para dar un acabado profesional a tus documentos. Este material resistente no solo protege tus papeles de la humedad y el desgaste, sino que tambien ofrece un aspecto elegante y pulido. Ideal para presentaciones, informes y cualquier proyecto que requiera un toque de calidad y durabilidad.', 3886.00, 20, 20, true, false, 'https://www.abastece.co/abastece/images/9150.jpg'),
('c3333333-3333-3333-3333-333333333333', 'AZ Carta Norma Azul 500708', 'az-carta-norma-azul-500708-1197', 'AZ Carta Azul - Norma 500708 Calidad y Color para Tus Documentos El AZ Carta Azul, conforme a la norma 500708, es la opción ideal para quienes buscan un papel de calidad y un toque vibrante en sus proyectos. Perfecto para impresiones, presentaciones o trabajos escolares, este papel combina resistencia y un color intenso que realza cualquier documento. Su versatilidad lo hace adecuado para uso en oficinas, escuelas y hogares, asegurando que tus ideas brillen. ¡Eleva tus impresiones con el AZ Carta Azul y destaca en cada trabajo!', 4342.00, 20, 23, true, false, 'https://www.abastece.co/abastece/images/1197.jpg'),
('c3333333-3333-3333-3333-333333333333', 'AZ Carta Norma Plastificado Azul 557160', 'az-carta-norma-plastificado-azul-557160-0218', 'AZ Carta Plastificado Azul - Marca Norma 557160 Protección y Estilo para Tus Documentos Importantes El AZ Carta Plastificado Azul de la marca Norma 557160 es ideal para quienes buscan una presentación profesional y duradera de sus documentos. Este papel plastificado no solo protege tus impresiones de daños, sino que también realza los colores y el diseño de tus trabajos. Perfecto para informes, presentaciones o materiales de marketing, su acabado brillante añade un toque elegante a cualquier proyecto. Asegúrate de que tus documentos se mantengan en perfecto estado con el AZ Carta Plastificado Azul.', 4416.00, 20, 29, true, false, 'https://www.abastece.co/abastece/images/0218.jpg'),
('c3333333-3333-3333-3333-333333333333', 'AZ Carta Plastificado Negro Marca Troppi', 'az-carta-plastificado-negro-marca-troppi-74248', 'AZ Carta Plastificado Negro Marca Troppi Elegancia y resistencia para tus documentos El AZ Carta Plastificado Negro Troppi es la solucion ideal para proteger y presentar tus documentos con un acabado profesional y sofisticado. Su plastificado de alta calidad asegura que tus papeles esten a salvo de la humedad, el desgaste y el daño. Perfecto para oficinas, presentaciones importantes o cualquier documento que necesite un toque elegante y duradero.', 12382.00, 20, 42, true, false, 'https://www.abastece.co/abastece/images/74248.jpg'),
('c3333333-3333-3333-3333-333333333333', 'AZ Carta Plastificas Amarillo Marca Troppi', 'az-carta-plastificas-amarillo-marca-troppi-74251', 'AZ Carta Plastificado Amarillo Marca Troppi Proteccion brillante y colorida para tus documentos El AZ Carta Plastificado Amarillo Troppi es ideal para proteger y darle un toque vibrante a tus documentos de tamaño carta. Su plastificado de alta calidad asegura una mayor durabilidad frente al desgaste y la humedad, mientras que su color amarillo brillante destaca tus papeles de manera llamativa. Perfecto para documentos importantes, presentaciones o cualquier archivo que necesite una proteccion confiable y una apariencia energetica y visible.', 12382.00, 20, 15, true, false, 'https://www.abastece.co/abastece/images/74251.jpg'),
('c3333333-3333-3333-3333-333333333333', 'AZ Carta Troppi Plastificado Azul Brillante', 'az-carta-troppi-plastificado-azul-brillante-3047', 'AZ Carta Plastificado Azul Marca Troppi Durabilidad y proteccion con un toque de color El AZ Carta Plastificado Azul Troppi es ideal para darle un acabado resistente y profesional a tus documentos. Con un diseÃƒÂ±o en color azul y un plastificado de alta calidad, protege tus papeles de la humedad, el desgaste y otros daÃƒÂ±os. Perfecto para uso en oficinas, escuelas o para cualquier archivo que necesite una presentacion duradera y atractiva.', 12382.00, 20, 28, true, false, 'https://www.abastece.co/abastece/images/3047.jpg'),
('c3333333-3333-3333-3333-333333333333', 'AZ Carta Troppi Plastificado Rojo', 'az-carta-troppi-plastificado-rojo-74207', 'AZ Carta Plastificado Rojo Marca Troppi Proteccion y color para tus documentos importantes El AZ Carta Plastificado Rojo Troppi es la opcion perfecta para darle a tus documentos una proteccion duradera y un acabado atractivo. Con su plastificado de alta calidad y color rojo vibrante, mantiene tus papeles seguros de la humedad y el desgaste. Ideal para presentaciones, archivos importantes o cualquier documento que necesite un toque de color y resistencia extra.', 12382.00, 20, 45, true, false, 'https://www.abastece.co/abastece/images/74207.jpg'),
('c3333333-3333-3333-3333-333333333333', 'AZ Carta Troppi Plastificado Verde', 'az-carta-troppi-plastificado-verde-3048', 'AZ Carta Plastificado Verde - Marca: Troppi Organizacion y resistencia para tus documentos El archivador AZ en formato carta, plastificado y de color verde, ofrece una solucion duradera y elegante para mantener tus documentos en orden. Fabricado por la reconocida marca Troppi, garantiza calidad y resistencia para el uso diario en oficinas, empresas e instituciones academicas. Ã‚¡Optimiza tu espacio de trabajo con este archivador prÃƒ¡ctico y resistente!', 12382.00, 20, 41, true, false, 'https://www.abastece.co/abastece/images/3048.jpg'),
('c3333333-3333-3333-3333-333333333333', 'AZ Carta Troppi Plastificado Verde Lima', 'az-carta-troppi-plastificado-verde-lima-70840', 'AZ Carta Plastificado Verde Lima Marca Troppi Archivo eficiente con codificación visual para control documental estandarizado Archivador tipo AZ tamaño carta plastificado en color verde lima, marca Troppi, fabricado en cartón rígido recubierto con película plástica de alta resistencia, diseñado para almacenamiento de documentos perforados con mecanismo de anillos reforzados que garantiza sujeción estable y uso prolongado; su acabado permite protección contra desgaste, identificación visual rápida y organización estructurada de archivos, contribuyendo a la estandarización del sistema documental y a la continuidad operativa en entornos administrativos que requieren orden, trazabilidad y eficiencia en la gestión de información.', 12382.00, 20, 23, true, false, 'https://www.abastece.co/abastece/images/70840.jpg'),
('c3333333-3333-3333-3333-333333333333', 'AZ Media Carta Azul', 'az-media-carta-azul-77172', 'AZ Media Carta Azul Organización documental eficiente con identificación cromática para control operativo Archivador tipo AZ media carta en color azul, fabricado en cartón rígido plastificado de alta resistencia, diseñado para el almacenamiento y archivo de documentos perforados mediante sistema de anillos reforzados que asegura sujeción estable y uso continuo; su acabado proporciona protección contra el desgaste, codificación visual inmediata y orden estructurado de información, contribuyendo a la estandarización del sistema de archivo y a la continuidad operativa en entornos administrativos que requieren eficiencia, trazabilidad y gestión documental organizada.', 8400.00, 20, 25, true, false, 'https://www.abastece.co/abastece/images/77172.jpg'),
('c3333333-3333-3333-3333-333333333333', 'AZ Medio Oficio Abastece Azul Plastificado', 'az-medio-oficio-abastece-azul-plastificado-0523', 'AZ Medio Oficio Azul Plastificado: Organización y Protección para tus Documentos Destaca con Elegancia y Durabilidad El AZ Medio Oficio Azul Plastificado es la solución perfecta para organizar y proteger tus documentos de manera elegante. Su tamaño medio oficio te ofrece un espacio adecuado para guardar hojas, informes, presentaciones y más. El plastificado en color azul no solo brinda un toque de estilo, sino que también proporciona una capa protectora que resiste el desgaste y el deterioro diario. Mantén tus documentos seguros con este AZ Medio Oficio Plastificado.', 3886.00, 20, 27, true, false, 'https://www.abastece.co/abastece/images/0523.jpg'),
('c3333333-3333-3333-3333-333333333333', 'AZ Oficio Abastece Plastificado Azul', 'az-oficio-abastece-plastificado-azul-9151', 'Az Oficio Azul Plastificado Abastece: Durabilidad y Estilo para tus Documentos Ideal para Presentaciones y Archivos Profesionales El Az Oficio Azul Plastificado de la marca Abastece es perfecto para proteger y presentar tus documentos importantes con un toque profesional. Su material plastificado garantiza una mayor durabilidad y resistencia al desgaste, manteniendo tus papeles en excelente estado. Ideal para oficinas, presentaciones y archivos, este producto combina funcionalidad y estetica. ¡Organiza tus documentos con confianza y estilo con Abastece!', 3895.00, 20, 28, true, false, 'https://www.abastece.co/abastece/images/9151.jpg'),
('c3333333-3333-3333-3333-333333333333', 'AZ Oficio Norma Azul 500709', 'az-oficio-norma-azul-500709-1140', 'AZ Oficio Azul Norma 500709 Organización y resistencia para tus documentos El archivador AZ Oficio Azul Norma 500709 es perfecto para almacenar y clasificar tus documentos de manera segura y ordenada. Su diseño resistente garantiza una larga durabilidad, ideal para oficinas y espacios de estudio. ¡Mantén tus archivos siempre organizados con Norma!', 4376.00, 20, 32, true, false, 'https://www.abastece.co/abastece/images/1140.jpg'),
('c3333333-3333-3333-3333-333333333333', 'AZ Oficio Norma Plastificado Azul 557159', 'az-oficio-norma-plastificado-azul-557159-0217', 'AZ Oficio Plastificado Azul Norma 557159 Organización y durabilidad para tus documentos El archivador AZ en tamaño oficio, plastificado en color azul, es ideal para almacenar y proteger documentos importantes. Su diseño resistente y sistema de anillado facilitan el acceso y la organización eficiente. ¡Optimiza tu archivo con este práctico y duradero organizador!', 66326.00, 20, 30, true, false, 'https://www.abastece.co/abastece/images/0217.jpg'),
('c3333333-3333-3333-3333-333333333333', 'AZ Oficio Plastificado Naranja Marca Troppi', 'az-oficio-plastificado-naranja-marca-troppi-75132', 'AZ Oficio Plastificado Naranja Marca Troppi Archivo de alto impacto visual para organización documental eficiente y estandarizada Archivador tipo AZ oficio plastificado en color naranja, marca Troppi, fabricado en cartón rígido recubierto con película plástica de alta resistencia, diseñado para el almacenamiento de documentos perforados mediante sistema de anillos reforzados que garantiza sujeción estable y uso prolongado; su estructura permite protección contra el desgaste, identificación cromática inmediata y organización eficiente de archivos, contribuyendo a la estandarización del sistema documental y a la continuidad operativa en entornos administrativos que requieren orden, trazabilidad y gestión documental ágil.', 12382.00, 20, 43, true, false, 'https://www.abastece.co/abastece/images/75132.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Az Oficio Plastificado Verde', 'az-oficio-plastificado-verde-3049', 'AZ Oficio Plastificado Verde Organización documental robusta con codificación visual para control eficiente de archivos Archivador tipo AZ oficio plastificado en color verde, fabricado en cartón rígido de alta densidad recubierto con película plástica resistente al desgaste, diseñado para el almacenamiento de documentos perforados mediante sistema de anillos metálicos reforzados que aseguran sujeción firme y uso continuo; su acabado permite protección estructural del contenido, identificación cromática rápida y ordenamiento documental eficiente, contribuyendo a la estandarización de procesos de archivo y a la continuidad operativa en entornos administrativos que requieren organización, trazabilidad y gestión documental consistente.', 15921.00, 20, 46, true, false, 'https://www.abastece.co/abastece/images/3049.jpg'),
('c3333333-3333-3333-3333-333333333333', 'AZ Oficio Troppi Plastificada Verde', 'az-oficio-troppi-plastificada-verde-5506', 'AZ Plastificada Oficio Verde - Marca Troppi Organización y resistencia para tus documentos El archivador AZ plastificado en tamaño oficio y color verde de la marca Troppi es ideal para mantener tus documentos ordenados y protegidos. Su cubierta plastificada garantiza durabilidad y un acabado profesional, perfecto para oficinas, empresas e instituciones. ¡Optimiza tu archivo con la calidad y resistencia de Troppi!', 12382.00, 20, 16, true, false, 'https://www.abastece.co/abastece/images/5506.jpg'),
('c3333333-3333-3333-3333-333333333333', 'AZ Oficio Troppi Plastificado Azul Brillante', 'az-oficio-troppi-plastificado-azul-brillante-9188', 'Az Oficio Plastificado Azul Marca Troppi - Resistencia y Presentacion Profesional Perfecto para proteger y organizar tus documentos importantes El Az Oficio Plastificado Azul Marca Troppi es la opcion ideal para mantener tus documentos organizados y protegidos. Fabricado con materiales de alta calidad, este az plastificado ofrece una resistencia excepcional, asegurando que tus papeles estan protegidos contra daños como humedad, rasgaduras o suciedad. Su diseoo en color azul le da un toque profesional, perfecto para la oficina, archivos personales o presentaciones. Con el Az Oficio Troppi, tus documentos estaran bien organizados y protegidos durante mucho mas tiempo, brindando una presentacion impecable en todo momento.', 12382.00, 20, 19, true, false, 'https://www.abastece.co/abastece/images/9188.jpg'),
('c3333333-3333-3333-3333-333333333333', 'AZ Oficio Troppi Plastificado Rojo', 'az-oficio-troppi-plastificado-rojo-9189', 'AZ Oficio Plastificado Rojo Marca Troppi Proteccion y presentacion vibrante para tus documentos El AZ Oficio Plastificado Rojo Troppi es ideal para mantener tus documentos de tamaÃƒÂ±o oficio protegidos y con un acabado profesional. Su plastificado de alta calidad asegura durabilidad y resistencia al desgaste, al tiempo que su color rojo brillante aporta un toque de dinamismo y visibilidad. Perfecto para archivos, presentaciones o cualquier documento que necesite una proteccion extra y un acabado vibrante.', 5099.00, 20, 25, true, false, 'https://www.abastece.co/abastece/images/9189.jpg'),
('c3333333-3333-3333-3333-333333333333', 'AZ OficioTroppi Plastificado Negro', 'az-oficiotroppi-plastificado-negro-73630', 'AZ Oficio Plastificado Negro Marca Troppi Protección y sofisticación para tus documentos El AZ Oficio Plastificado Negro Troppi ofrece una excelente protección para documentos tamaño oficio, manteniéndolos seguros y en perfecto estado. Su plastificado de alta calidad proporciona resistencia al desgaste y la humedad, mientras que su color negro le da un toque elegante y profesional. Ideal para presentaciones, archivos importantes o cualquier documento que necesite protección y una apariencia sofisticada.', 12383.00, 20, 38, true, false, 'https://www.abastece.co/abastece/images/73630.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Bandas De Caucho Color Crema Ref 22 Caja', 'bandas-de-caucho-color-crema-ref-22-caja-0042', 'Bandas de Caucho Color Crema Ref 22 Caja Bandas de Caucho de Alta Calidad para Diversos Usos Las Bandas de Caucho Color Crema Ref 22 son ideales para sujetar, organizar y almacenar objetos con facilidad. Vienen en una práctica caja que asegura su fácil acceso y almacenamiento. Con un color crema neutro y fabricadas con materiales resistentes, estas bandas de caucho ofrecen durabilidad y flexibilidad para una variedad de aplicaciones, desde oficinas hasta uso doméstico. Perfectas para mantener tus objetos ordenados y asegurados de forma eficiente.', 629.00, 20, 42, true, false, 'https://www.abastece.co/abastece/images/0042.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Bandas De Caucho Color Crema Ref. 22 Paquete X Kilo', 'bandas-de-caucho-color-crema-ref-22-paquete-x-kilo-0620', 'Bandas de Caucho Color Crema Ref. 22 Paquete por Kilo Resistencia y Versatilidad para tus Proyectos Las Bandas de Caucho Color Crema Ref. 22 Paquete por Kilo son ideales para diversas aplicaciones tanto en el hogar como en el entorno laboral. Estas bandas están fabricadas con caucho de alta calidad, lo que les proporciona una excelente elasticidad y resistencia. Perfectas para atar, sujetar, organizar y asegurar objetos de manera eficiente, estas bandas se destacan por su color crema que combina con diferentes estilos y usos.', 11998.00, 20, 41, true, false, 'https://www.abastece.co/abastece/images/0620.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Bandas De Caucho De Colores Ref: 18 454gr', 'bandas-de-caucho-de-colores-ref-18-454gr-75424', 'Bandas de Caucho de Colores Ref: 18 454 g Organización y sujeción eficiente con identificación visual para gestión operativa ágil Bandas elásticas de caucho natural en presentación de 454 g, referencia 18, elaboradas en material flexible de alta resistencia con variedad de colores para facilitar la clasificación visual de objetos, documentos o insumos; su composición permite alta elasticidad controlada, resistencia al uso repetitivo y agarre seguro sin deterioro rápido, contribuyendo a la estandarización de procesos de organización y a la continuidad operativa en entornos administrativos, logísticos y comerciales donde se requiere eficiencia, orden y rápida identificación de materiales.', 14935.00, 20, 16, true, false, 'https://www.abastece.co/abastece/images/75424.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Bandas Elasticas De Caucho Siliconado Bolsa 450gr Aprox', 'bandas-elasticas-de-caucho-siliconado-bolsa-450gr-aprox-77274', 'Bandas Elásticas de Caucho Siliconado – Bolsa x 450 g Aprox. Gestión técnica de organización de suministros y eficiencia operativa Este insumo estratégico para la clasificación y sujeción de elementos está fabricado con una mezcla de caucho y silicona de alta calidad, lo que proporciona una elasticidad superior y una mayor resistencia a la cristalización por factores ambientales. Su diseño permite una sujeción firme sin maltratar las superficies de los objetos, facilitando la estandarización de procesos en el archivo de documentos, embalaje de muestras y organización de inventarios. La presentación en bolsa de 450 g asegura la continuidad operativa de las estaciones de empaque y áreas administrativas, optimizando la eficiencia logística mediante un suministro de alto rendimiento y durabilidad. Su implementación técnica contribuye al bienestar del equipo al facilitar el orden sistemático y la manipulación segura de materiales dentro de la organización.', 9050.00, 20, 30, true, false, 'https://www.abastece.co/abastece/images/77274.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Banderitas Plasticas 5 Colores Neon Surtidos x125', 'banderitas-plasticas-5-colores-neon-surtidos-x125-9287', 'Banderitas Plásticas 5 Colores Surtidos Paq. x 125 u. Marcación visual eficiente para organización y señalización documental ágil Banderitas adhesivas plásticas en presentación de 125 unidades con 5 colores surtidos, fabricadas en material flexible de alta resistencia con adhesivo reposicionable que permite señalización temporal o permanente en documentos, carpetas y archivos; su diseño facilita identificación rápida de información, clasificación visual por colores y uso repetido sin deterioro del soporte, contribuyendo a la estandarización de procesos de organización documental y a la continuidad operativa en entornos administrativos, educativos y corporativos que requieren eficiencia en la gestión de información.', 1024.00, 20, 27, true, false, 'https://www.abastece.co/abastece/images/9287.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Banderitas Post It 3M 4 Colores Surtidos Paq.x140u.', 'banderitas-post-it-3m-4-colores-surtidos-paqx140u-2300', 'Banderitas Post It 3M: Organiza y Destaca tus Ideas Versatilidad y Color para tu Organizacion Diaria Presentamos las Banderitas Post It 3M en 4 colores surtidos, con un paquete de 140 unidades. Perfectas para resaltar informacion importante, hacer anotaciones rapidas o marcar paginas, estas banderitas son el complemento ideal para estudiantes y profesionales. Su adhesivo de alta calidad garantiza que se mantendran en su lugar sin dañar tus documentos. Haz que tus ideas brillen y manten todo a la vista!', 13744.00, 20, 48, true, false, 'https://www.abastece.co/abastece/images/2300.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Bisturi Grande Plastico', 'bisturi-grande-plastico-0141', 'Bisturí Grande Plástico: Precisión y Seguridad para tus Cortes Instrumento de Corte de Alta Precisión con Mango de Plástico Resistente El **Bisturí Grande Plástico** es una herramienta ideal para trabajos de corte de precisión, como en actividades de modelismo, artesanía o en aplicaciones médicas. Su mango de plástico ergonómico y resistente asegura un agarre cómodo y seguro durante su uso, mientras que la hoja de alta calidad garantiza cortes finos y precisos. Perfecto para tareas que requieren detalle y control, este bisturí es una opción confiable tanto para profesionales como para aficionados.', 438.00, 20, 36, true, false, 'https://www.abastece.co/abastece/images/0141.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Bisturi Metalico Grande Con Riel', 'bisturi-metalico-grande-con-riel-4103', 'Bisturí Metálico Grande con Riel Corte preciso y controlado para aplicaciones técnicas de alta exigencia Bisturí de cuerpo metálico de alta resistencia en formato grande con sistema de riel guía, diseñado para cortes precisos en materiales como papel, cartón, vinilos y superficies livianas, incorporando mecanismo de ajuste de hoja que mejora la estabilidad durante el uso; su estructura permite mayor control de corte, seguridad en la manipulación y durabilidad operativa, contribuyendo a la estandarización de procesos de trabajo manual y a la continuidad operativa en entornos administrativos, gráficos y técnicos donde la precisión es determinante.', 2324.00, 20, 43, true, false, 'https://www.abastece.co/abastece/images/4103.jpg')
INSERT INTO products (category_id, name, slug, description, price, discount, stock, active, featured, main_image_url) VALUES
('c3333333-3333-3333-3333-333333333333', 'Bisturi Metalico Stanley Industrial 10-175', 'bisturi-metalico-stanley-industrial-10-175-70720', 'Bisturí Metálico Industrial Ref-10-175 – Stanley Precisión y durabilidad para cortes industriales de alta calidad El Bisturí Metálico Industrial Ref-10-175 de Stanley es la herramienta perfecta para realizar cortes precisos y de alta calidad en una variedad de materiales, desde cartón y plástico hasta tejidos y más. Su hoja metálica de alta resistencia está diseñada para ofrecer un corte limpio y exacto, mientras que su mango ergonómico proporciona un agarre cómodo y seguro, ideal para trabajos prolongados. Este bisturí es especialmente recomendado para aplicaciones industriales, manualidades, modelismo y otros trabajos que requieran cortes finos y detallados. ¡Confía en la calidad y precisión de Stanley para tus proyectos más exigentes con el Bisturí Metálico Industrial Ref-10-175!', 19992.00, 20, 48, true, true, 'https://www.abastece.co/abastece/images/70720.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Bisturi Metalplastico 9mm Pequeño Marca Olfa Ref: 180 Black', 'bisturi-metalplastico-9mm-pequeno-marca-olfa-ref-180-black-70425', 'Bisturí Metalplástico 9 mm Pequeño Marca Olfa Ref: 180 Black Corte preciso y seguro en formato compacto para tareas técnicas de alta frecuencia Bisturí de cuerpo metalplástico con hoja de 9 mm en formato pequeño, marca Olfa referencia 180 Black, diseñado para cortes finos en papel, cartón, vinilo y materiales livianos, incorporando sistema de guía deslizante que mejora el control de la hoja y la estabilidad en el uso; su diseño permite precisión en cortes detallados, manejo ergonómico continuo y seguridad operativa en trabajos repetitivos, contribuyendo a la estandarización de procesos de corte manual y a la continuidad operativa en entornos administrativos, gráficos y técnicos donde la eficiencia y exactitud son esenciales.', 18120.00, 20, 18, true, true, 'https://www.abastece.co/abastece/images/70425.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Bisturi Metalplastico Encauchetado Grande', 'bisturi-metalplastico-encauchetado-grande-4104', 'Bisturí Metalplástico Encauchetado Grande 18 mm Control superior y seguridad en cortes de alta exigencia operativa Bisturí de cuerpo metalplástico encauchetado con hoja de 18 mm en formato grande, diseñado para cortes en materiales de mayor densidad como cartón grueso, vinilos industriales y láminas livianas, incorporando recubrimiento en caucho antideslizante que mejora el agarre y la estabilidad durante el uso; su configuración permite mayor precisión en cortes exigentes, reducción de deslizamientos y durabilidad en uso continuo, contribuyendo a la estandarización de procesos de corte técnico y a la continuidad operativa en entornos administrativos, gráficos e industriales donde la seguridad y eficiencia son prioritarias.', 1617.00, 20, 35, true, false, 'https://www.abastece.co/abastece/images/4104.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Bisturi Pequeño Metalplastico Autobloqueo 9mm KCS9', 'bisturi-pequeno-metalplastico-autobloqueo-9mm-kcs9-71324', 'Bisturí Pequeño Metalplástico 9 mm Autobloqueo – Ref: KCS9 Precisión y seguridad en tus tareas de corte y diseño El Bisturí Pequeño Metalplástico 9 mm Autobloqueo Ref: KCS9 es la herramienta perfecta para trabajos que requieren cortes finos y de alta precisión. Con su diseño compacto y sistema de autobloqueo, garantiza una experiencia de uso segura y controlada. Su hoja de 9 mm es ideal para realizar cortes detallados en papel, cartulina, plásticos delgados y otros materiales ligeros. Su cuerpo de metalplástico asegura resistencia y ligereza, lo que lo hace cómodo para el uso prolongado. Ideal para artistas, diseñadores, o para el uso en oficinas y laboratorios. ¡Asegura cortes perfectos y precisos con el Bisturí Pequeño Metalplástico KCS9!', 3046.00, 20, 54, true, false, 'https://www.abastece.co/abastece/images/71324.jpg'),
('c3333333-3333-3333-3333-333333333333', 'bisturi pequeño plastico', 'bisturi-pequeno-plastico-0142', 'Bisturí Pequeño Plástico Precisión y seguridad en cada corte El Bisturí Pequeño Plástico es una herramienta de precisión diseñada para cortes finos y detallados. Su mango de plástico ergonómico garantiza un agarre cómodo y seguro, permitiendo un control total durante su uso. Ideal para trabajos de precisión en manualidades, modelismo, arte, o incluso en procedimientos médicos o de laboratorio, este bisturí es ligero y fácil de manejar. Su hoja afilada asegura cortes limpios y exactos, mientras que el diseño plástico lo hace resistente y fácil de limpiar. Con el Bisturí Pequeño Plástico, podrás realizar cortes detallados de manera rápida y eficiente, asegurando resultados profesionales en cada proyecto.', 270.00, 20, 25, true, false, 'https://www.abastece.co/abastece/images/0142.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Bisturi Punta de Lanza', 'bisturi-punta-de-lanza-0399', 'Bisturi Punta de Lanza Precision y Control para Cortes Finos y Detallados El Bisturi Punta de Lanza es una herramienta de corte de alta precision, diseñada para realizar cortes finos y detallados en una variedad de materiales. Con su punta afilada y resistente, este bisturi permite una mayor exactitud en trabajos de precision, como modelado, diseccion, y manualidades. Su diseño ergonomico y ligero facilita un control total durante el uso, reduciendo la fatiga. Ideal para profesionales en areas como la medicina, la veterinaria, la cirugia, o actividades como el arte y la creacion de prototipos, este bisturi asegura cortes limpios y eficientes. Es la herramienta perfecta para quienes requieren precision en cada detalle.', 2613.00, 20, 40, true, false, 'https://www.abastece.co/abastece/images/0399.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Bisturi Retractil 7pg + 4 Cuchillas Truper Ref 16950', 'bisturi-retractil-7pg-4-cuchillas-truper-ref-16950-74772', 'Bisturí Retráctil 7&quot; + 4 Cuchillas Truper Ref. 16950 Corte seguro y versátil con sistema retráctil para mayor control operativo Bisturí retráctil de 7 pulgadas marca Truper referencia 16950, que incluye 4 cuchillas de repuesto, diseñado para cortes en materiales como cartón, plástico, vinilo y superficies livianas, incorporando mecanismo retráctil que permite proteger la hoja cuando no está en uso; su estructura proporciona mayor seguridad en la manipulación, precisión en cortes continuos y reducción de riesgos operativos, contribuyendo a la estandarización de procesos de corte manual y a la continuidad operativa en entornos administrativos, logísticos y técnicos donde la eficiencia y el control son esenciales.', 21741.00, 20, 44, true, false, 'https://www.abastece.co/abastece/images/74772.jpg'),
